 public static void main(String[]args)throws Exception{
 c("ui.symbol.MusicFont").getMethod("populateAllSymbols").invoke(null);Object book=c("sheet.Book").getMethod("loadBook",Path.class).invoke(null,Path.of(args[0])),sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet");List<?>systems=(List<?>)call(sheet,"getSystems");List<Object>retrievers=new ArrayList<>();for(Object sys:systems){Object r=c("sheet.stem.StemsRetriever").getConstructor(c("sheet.SystemInfo")).newInstance(sys);retrievers.add(r);call(r,"process");}Object before=beams(systems);for(int i=0;i<systems.size();i++){call(retrievers.get(i),"finalizeBeams");call(call(systems.get(i),"getSig"),"contextualize");}Object after=beams(systems);new ObjectMapper().writerWithDefaultPrettyPrinter().writeValue(Path.of(args[1]).toFile(),obj("native_outputs_used",false,"scope","original actual process on same image HEADS, ordered finalizeBeams and system contextualization; not whole SIG parity", "before_epilog",before,"after_epilog",after));System.exit(0);
 }
